import {suit,rank,points,legal,play,winner,roundScores,shuffle} from '../../src/game.js';
export function choosePass(hand){const count=[0,0,0,0];hand.forEach(c=>count[suit(c)]++);return [...hand].sort((a,b)=>danger(b)-danger(a)).slice(0,3);function danger(c){return (c===36?24:c===37?22:c===38?21:rank(c))+(suit(c)===3?4:0)+(count[suit(c)]<=3&&suit(c)!==2?7:0);}}
// Only this observation crosses the worker boundary; opponents' hands are absent.
export function observe(s,p,known={}){return {player:p,hand:[...s.hands[p]],counts:s.hands.map(h=>h.length),turn:s.turn,trick:structuredClone(s.trick),taken:[...s.taken],broken:s.broken,completed:s.completed,history:structuredClone(s.history),voids:s.voids.map(v=>[...v]),known:structuredClone(known)};}
export function sample(o,rng=Math.random){const seen=new Set([...o.hand,...o.history.flatMap(t=>t.trick.map(x=>x.card)),...o.trick.map(x=>x.card)]);const pool=Array.from({length:52},(_,i)=>i).filter(c=>!seen.has(c));const hands=Array.from({length:4},()=>[]);hands[o.player]=[...o.hand];for(const [key,cards] of Object.entries(o.known||{})){const p=Number(key);if(p===o.player)continue;for(const c of cards){const ix=pool.indexOf(c);if(ix>=0){hands[p].push(c);pool.splice(ix,1);}}}
// Randomized constrained backtracking preserves every publicly revealed void.
const capacities=o.counts.map((n,p)=>n-hands[p].length);let nodes=0;shuffle(pool,rng);pool.sort((a,b)=>allowed(a).length-allowed(b).length);function allowed(c){return [0,1,2,3].filter(p=>p!==o.player&&capacities[p]>0&&!o.voids[p].includes(suit(c)));}function assign(i){if(++nodes>30000)return false;if(i===pool.length)return true;const c=pool[i];for(const p of shuffle(allowed(c),rng)){hands[p].push(c);capacities[p]--;if(assign(i+1))return true;hands[p].pop();capacities[p]++;}return false;}if(!assign(0))return null;return {...structuredClone(o),hands};}
export function policy(s,rng=Math.random){const choices=legal(s);if(choices.length===1)return choices[0];if(rng()<0.08)return choices[Math.floor(rng()*choices.length)];const trick=s.trick;const lead=trick.length?suit(trick[0].card):-1;const current=trick.length?winner(trick):-1;const top=trick.length?Math.max(...trick.filter(x=>suit(x.card)===lead).map(x=>rank(x.card))):-1;const pot=trick.reduce((n,x)=>n+points(x.card),0);return choices.reduce((best,c)=>score(c)>score(best)?c:best);function score(c){if(!trick.length)return -rank(c)-(suit(c)===2?3:0)-points(c)*2;if(suit(c)!==lead)return points(c)*20+rank(c);const wins=rank(c)>top;if(!wins)return rank(c)+points(c)*4;if(trick.length===3&&pot===0)return rank(c)*0.7-points(c)*5;return -20-pot*10-rank(c)-points(c)*10+(current===s.turn?0:0);}}
export function decide(o,{milliseconds=1200,minSamples=16,rng=Math.random}={}){const base={...o,hands:Array.from({length:4},(_,p)=>p===o.player?o.hand:[])};const choices=legal(base);if(choices.length===1)return {card:choices[0],samples:0};const sums=choices.map(()=>0),squares=choices.map(()=>0);const deadline=performance.now()+milliseconds;let n=0;do{const world=sample(o,rng);if(!world)break;for(let i=0;i<choices.length;i++){const s=structuredClone(world);play(s,choices[i]);while(s.completed<13)play(s,policy(s,rng));const scores=roundScores(s.taken);const cost=scores[o.player]-scores.reduce((n,x,p)=>n+(p===o.player?0:x),0)/3;sums[i]+=cost;squares[i]+=cost*cost;}n++;}while(n<minSamples||performance.now()<deadline);if(!n)return {card:policy(base,rng),samples:0};const means=sums.map(x=>x/n);const ix=means.indexOf(Math.min(...means));return {card:choices[ix],samples:n,expected:means[ix],estimates:choices.map((card,i)=>({card,cost:means[i],stderr:Math.sqrt(Math.max(0,squares[i]/n-means[i]**2)/n)}))};}
